const pt: Record<string, string> = {}, es: Record<string, string> = {};
for (const [en, p, s] of T) { pt[en] = p; es[en] = s; }
// Coded keys resolve through their English label.
for (const [k, en] of Object.entries(EN_CODES)) { if (pt[en]) pt[k] = pt[en]; if (es[en]) es[k] = es[en]; }
export const DICT: Record<Lang, Record<string, string>> = { en: EN_CODES, pt, es };
